/* ============================================================
   places.js: every country and first-level region on Earth.

   Loaded on demand the first time someone types in the birthplace
   field, so it never costs the initial page load. It exists because
   the live geocoder is a *city* database: searching it for "Texas"
   or "Bavaria" returns obscure villages of that name rather than the
   state, which made the birthplace field feel broken for anyone who
   wanted to name a region or a country instead of a town.

   Country row: [name, iso2, lat, lon, capital]
   Region row:  [name, iso2, lat, lon]
   Coordinates are the administrative centroid, rounded to 2dp.
   Source: dr5hn/countries-states-cities-database.
   ============================================================ */

