const ISO_TO_NAME = Object.fromEntries(COUNTRIES.map((c) => [c[1], c[0]]));

/**
 * Countries and regions matching a query, best first.
 * Ranked so that a whole-word or prefix hit beats a substring hit, and a
 * country beats a region: someone typing "Ind" almost certainly means India
 * or Indonesia rather than a district called Indi.
 */
export function searchRegions(query, limit = 6) {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];
  const out = [];

  const score = (name) => {
    const n = name.toLowerCase();
    if (n === q) return 0;
    if (n.startsWith(q)) return 1;
    if (n.includes(" " + q)) return 2;
    if (n.includes(q)) return 3;
    return -1;
  };

  for (const [name, iso, lat, lon] of COUNTRIES) {
    const s = score(name);
    if (s >= 0) out.push({ s, kind: "country", name, iso, lat, lon });
  }
  for (const [name, iso, lat, lon] of REGIONS) {
    const s = score(name);
    if (s >= 0) out.push({ s: s + 0.5, kind: "region", name, iso, lat, lon });
  }

  return out
    .sort((a, b) => a.s - b.s || a.name.length - b.name.length)
    .slice(0, limit)
    .map((r) => ({
      lat: r.lat,
      lon: r.lon,
      name: r.name,
      admin1: r.kind === "region" ? r.name : "",
      country: r.kind === "country" ? r.name : ISO_TO_NAME[r.iso] || "",
      countryCode: r.iso,
      timezone: "",
      kind: r.kind,
      label: r.kind === "country" ? r.name : [r.name, ISO_TO_NAME[r.iso] || ""].filter(Boolean).join(", "),
    }));
}
